/**
 * DB 스키마.
 *
 * 파일(.sql)이 아니라 문자열 상수로 둔다.
 * Next.js 번들 환경에서는 readFileSync(new URL(...)) 이 동작하지 않아
 * 서버 컴포넌트가 스키마를 읽지 못한다(실측 확인).
 */
export type SqlDialect = "sqlite" | "postgres";

/**
 * 스키마 DDL 을 방언에 맞게 돌려준다. 정본은 아래 SQLite 문법(SCHEMA_SQL)이고,
 * Postgres 는 최소 치환만 한다:
 *   - INTEGER PRIMARY KEY AUTOINCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
 *   - 그 외 INTEGER → BIGINT (id 컬럼 32비트 오버플로 예방 겸)
 * 나머지(TEXT·REAL·DEFAULT·PRIMARY KEY(...)·ON CONFLICT·CREATE INDEX IF NOT EXISTS)는
 * 두 엔진 모두 그대로 받는다. PRAGMA 는 SCHEMA_SQL 에 없다(openDb 에서 sqlite 에만 건다).
 */
export function schemaSqlFor(dialect: SqlDialect): string {
  if (dialect === "sqlite") return SCHEMA_SQL;
  return SCHEMA_SQL
    .replace(/INTEGER PRIMARY KEY AUTOINCREMENT/g, "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY")
    .replace(/\bINTEGER\b/g, "BIGINT");
}

export const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS cases (
  request_id           INTEGER PRIMARY KEY,
  request_id_formatted TEXT    NOT NULL,
  subject              TEXT    NOT NULL DEFAULT '',
  status               TEXT    NOT NULL DEFAULT '',
  priority             TEXT    NOT NULL DEFAULT '',
  category             TEXT    NOT NULL DEFAULT '',
  party_name           TEXT    NOT NULL DEFAULT '',
  party_site_number    TEXT    NOT NULL DEFAULT '',
  created_on           TEXT    NOT NULL DEFAULT '',
  created_on_ms        INTEGER,
  last_updated         TEXT    NOT NULL DEFAULT '',
  last_updated_ms      INTEGER,
  first_seen_at        TEXT    NOT NULL,
  last_fetched_at      TEXT    NOT NULL,
  raw_json             TEXT    NOT NULL DEFAULT '{}',
  -- 케이스를 최초 등록할 때 우리가 쓴 본문. 스레드가 아니라 별도 필드로 온다.
  description_html     TEXT    NOT NULL DEFAULT '',
  description_text     TEXT    NOT NULL DEFAULT '',
  -- 답변 등록 시 필요한 낙관적 잠금 값
  case_version         INTEGER,
  -- SR 작성 폼의 Product / Component. 실제로 쓰인 조합을 모으기 위해 저장한다.
  product_id           INTEGER,
  product_name         TEXT NOT NULL DEFAULT '',
  component_id         INTEGER,
  component_name       TEXT NOT NULL DEFAULT '',
  -- 팀(공용 계정) 소유. 신규 DB 는 여기서 바로 만든다(런타임 ALTER 불필요 → PG 소유권 문제 회피).
  -- 기존 SQLite DB 는 아래 ADDED_COLUMNS 마이그레이션이 채운다.
  team_id              TEXT NOT NULL DEFAULT 'default'
);

CREATE INDEX IF NOT EXISTS idx_cases_last_updated ON cases(last_updated_ms DESC);

CREATE TABLE IF NOT EXISTS threads (
  thread_id      INTEGER PRIMARY KEY,
  request_id     INTEGER NOT NULL,
  author_unit    TEXT    NOT NULL DEFAULT '',
  author_unit_id INTEGER NOT NULL DEFAULT 0,
  -- 1 = 우리가 쓴 글, 0 = 상대(Broadcom) 답변
  is_ours        INTEGER NOT NULL DEFAULT 0,
  res_date_ms    INTEGER,
  res_date_val   TEXT    NOT NULL DEFAULT '',
  body_html      TEXT    NOT NULL DEFAULT '',
  body_text      TEXT    NOT NULL DEFAULT '',
  fetched_at     TEXT    NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_threads_request ON threads(request_id, res_date_ms DESC);

-- 수집 실행 이력.
-- status 를 3값으로 구분하는 것이 핵심이다.
--   success         : 정상 수집
--   session_expired : 세션이 끊겨 조회하지 못함  <- '새 답변 0건'과 절대 같지 않다
--   failed          : 그 외 실패
CREATE TABLE IF NOT EXISTS runs (
  run_id        INTEGER PRIMARY KEY AUTOINCREMENT,
  started_at    TEXT    NOT NULL,
  finished_at   TEXT,
  status        TEXT    NOT NULL,
  cases_seen    INTEGER NOT NULL DEFAULT 0,
  cases_changed INTEGER NOT NULL DEFAULT 0,
  new_threads   INTEGER NOT NULL DEFAULT 0,
  session_state TEXT    NOT NULL DEFAULT '',
  error         TEXT
);

CREATE INDEX IF NOT EXISTS idx_runs_started ON runs(started_at DESC);

-- 팀이 어디까지 확인했는지. 계정을 공유하므로 팀 단위 읽음 상태로 둔다.
-- last_read_thread_ms 보다 새로운 상대 답변이 있으면 '새 답변'이다.
-- NVD 에서 가져온 보안 취약점.
-- 우리가 지원하는 제품 키워드로 조회한 결과이며, 키워드 매칭이라 무관한 것이 섞일 수 있다.
-- dismissed = 1 이면 화면에서 숨긴다(관련 없다고 판단한 것).
CREATE TABLE IF NOT EXISTS cves (
  cve_id     TEXT NOT NULL,
  product    TEXT NOT NULL,
  keyword    TEXT NOT NULL DEFAULT '',
  severity   TEXT NOT NULL DEFAULT '',
  score      REAL,
  published  TEXT NOT NULL DEFAULT '',
  modified   TEXT NOT NULL DEFAULT '',
  summary    TEXT NOT NULL DEFAULT '',
  url        TEXT NOT NULL DEFAULT '',
  fetched_at TEXT NOT NULL,
  first_seen TEXT NOT NULL,
  dismissed  INTEGER NOT NULL DEFAULT 0,
  vector              TEXT NOT NULL DEFAULT '',
  attack_vector       TEXT NOT NULL DEFAULT '',
  attack_complexity   TEXT NOT NULL DEFAULT '',
  privileges_required TEXT NOT NULL DEFAULT '',
  user_interaction    TEXT NOT NULL DEFAULT '',
  impact_c            TEXT NOT NULL DEFAULT '',
  impact_i            TEXT NOT NULL DEFAULT '',
  impact_a            TEXT NOT NULL DEFAULT '',
  cwe                 TEXT NOT NULL DEFAULT '',
  references_json     TEXT NOT NULL DEFAULT '[]',
  affected_json       TEXT NOT NULL DEFAULT '[]',
  -- 한국어 번역. 한 번 만들면 다시 부르지 않는다.
  summary_ko          TEXT NOT NULL DEFAULT '',
  -- 담당자용 3줄 정리 (무엇이 / 영향 / 확인할 것)
  brief_ko            TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (cve_id, product)
);

CREATE INDEX IF NOT EXISTS idx_cves_published ON cves(published DESC);

-- Broadcom 기술문서(Knowledge Base).
-- 사이트맵에서 목록을 받고, 신규 문서만 본문을 받아 제품 태그(product-chip)로 거른다.
-- 제품 태그를 저장해 두면 그 뒤 개정분은 본문을 다시 안 받아도 우리 제품인지 판정된다.
-- matched 가 비어 있으면 우리 제품이 아니다(받아본 기록으로만 남긴다).
-- verdict 는 우리 환경 적합성 판정: '' 미판정 / match / maybe / no.
CREATE TABLE IF NOT EXISTS kb_articles (
  article_id  INTEGER PRIMARY KEY,
  slug        TEXT NOT NULL DEFAULT '',
  url         TEXT NOT NULL DEFAULT '',
  title       TEXT NOT NULL DEFAULT '',
  products    TEXT NOT NULL DEFAULT '',
  matched     TEXT NOT NULL DEFAULT '',
  lastmod     TEXT NOT NULL DEFAULT '',
  published   TEXT NOT NULL DEFAULT '',
  modified    TEXT NOT NULL DEFAULT '',
  issue       TEXT NOT NULL DEFAULT '',
  environment TEXT NOT NULL DEFAULT '',
  cause       TEXT NOT NULL DEFAULT '',
  resolution  TEXT NOT NULL DEFAULT '',
  fetched_at  TEXT NOT NULL,
  first_seen  TEXT NOT NULL,
  verdict     TEXT NOT NULL DEFAULT '',
  verdict_why TEXT NOT NULL DEFAULT '',
  judged_at   TEXT NOT NULL DEFAULT '',
  dismissed   INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_kb_matched ON kb_articles(matched, article_id DESC);

-- 케이스 첨부파일.
-- 파일 실체는 Broadcom 쪽(supportftp)에 있고 우리는 목록과 링크만 갖는다.
-- 204MB 짜리도 있어서 내려받아 보관하지 않는다.
CREATE TABLE IF NOT EXISTS attachments (
  document_id  INTEGER PRIMARY KEY,
  request_id   INTEGER NOT NULL,
  thread_id    INTEGER,
  doc_name     TEXT    NOT NULL DEFAULT '',
  doc_path     TEXT    NOT NULL DEFAULT '',
  content_type TEXT    NOT NULL DEFAULT '',
  file_size    INTEGER NOT NULL DEFAULT 0,
  uploaded_by  TEXT    NOT NULL DEFAULT '',
  uploaded_at  TEXT    NOT NULL DEFAULT '',
  uploaded_ms  INTEGER,
  fetched_at   TEXT    NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_attachments_request ON attachments(request_id, uploaded_ms DESC);

-- 종료 케이스 정리 결과.
-- 처음 요청할 때 만들어 저장하고, 이후에는 저장분을 그대로 돌려준다.
-- source: draft = 수집 데이터로 엮은 초안, ai = AI 로 다듬은 것
CREATE TABLE IF NOT EXISTS case_summaries (
  request_id   INTEGER NOT NULL,
  kind         TEXT    NOT NULL,
  content      TEXT    NOT NULL,
  source       TEXT    NOT NULL DEFAULT 'draft',
  generated_at TEXT    NOT NULL,
  PRIMARY KEY (request_id, kind)
);

-- SR 하나 ↔ 그 SR 로 끊은 Jira 티켓.
--
-- 두 가지에 쓴다.
--   1. SR 이 끝난 뒤 **어디에 댓글을 달지** 안다.
--   2. 자동 게시의 울타리. 이 행이 있는 SR 만 자동 대상이다 — 행은 새 생성 버튼을
--      거친 SR 에만 생기므로, 기능이 들어가기 **전**의 SR 은 구조적으로 빠진다.
--      (과거 SR 수십 건이 종료되면서 한꺼번에 Confluence 로 쏟아지는 것을 막는다)
--
-- case_summaries 를 kind='jira_issue' 로 재활용할 수도 있지만, 이건 요약이 아니라
-- 연결이고 이 값으로 외부에 글을 쓴다. 제 표를 둔다.
--
-- title_ko: 티켓 제목에 쓴 한글. 포털 SR 제목은 영문이라(한국어로 적으면 번역해서
--   올린다) 그 영문으로는 목록에서 무슨 일인지 읽히지 않는다. 그래서 번역 전 한글을
--   여기 남긴다 — 나중에 댓글이나 문서 제목에도 쓴다.
-- commented_at: 결과 댓글을 단 시각. 두 번 달지 않으려고 둔다.
CREATE TABLE IF NOT EXISTS sr_jira_links (
  request_id   INTEGER PRIMARY KEY,
  issue_key    TEXT    NOT NULL,
  issue_url    TEXT    NOT NULL DEFAULT '',
  track        TEXT    NOT NULL DEFAULT '',
  title_ko     TEXT    NOT NULL DEFAULT '',
  created_at   TEXT    NOT NULL,
  commented_at TEXT    NOT NULL DEFAULT '',
  -- 자동 게시를 몇 번 시도했나. 조건으로 대상을 고르는 구조라(스스로 낫는 대신)
  -- 영구히 실패하는 건을 매번 다시 집어 AI 를 때린다. 상한을 두려고 센다.
  publish_tries INTEGER NOT NULL DEFAULT 0,
  -- 결과 댓글을 몇 번 시도했나. 게시와 **따로** 센다 — 게시는 됐는데 댓글만 실패하는
  -- 경우가 있고, 그때 다시 집으려면 게시 횟수와 섞이면 안 된다.
  comment_tries INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS case_reads (
  request_id          INTEGER PRIMARY KEY,
  last_read_thread_ms INTEGER NOT NULL DEFAULT 0,
  read_at             TEXT    NOT NULL
);

-- 정기점검 보고서의 월별 인스턴스 입력값.
-- 결과(container_*)를 같이 저장하는 이유는 다음 달 "전월 대비 증감" 때문이다.
-- 이 값이 있으면 다음 달에는 입력 9개만 넣으면 된다.
-- month 는 'YYYY-MM'.
CREATE TABLE IF NOT EXISTS instance_counts (
  month                TEXT    PRIMARY KEY,
  bank_dev             REAL    NOT NULL,
  bank_prod            REAL    NOT NULL,
  bank_dr              REAL    NOT NULL,
  central_dev          REAL    NOT NULL,
  central_prod         REAL    NOT NULL,
  central_dr           REAL    NOT NULL,
  shared_dev           REAL    NOT NULL,
  shared_prod          REAL    NOT NULL,
  shared_dr            REAL    NOT NULL,
  container_bank_prod         REAL NOT NULL,
  container_bank_prod_shared  REAL NOT NULL,
  container_bank_dev          REAL NOT NULL,
  container_bank_dev_shared   REAL NOT NULL,
  container_central_prod      REAL NOT NULL,
  container_central_dev       REAL NOT NULL,
  -- 이 달을 계산할 때 실제로 쓴 전월값.
  -- 앞선 달이 저장돼 있으면 그 값이 들어가고, 첫 달이면 사람이 넣은 값이 들어간다.
  -- 남겨두면 "무엇과 비교한 증감인지"를 나중에도 알 수 있다.
  prev_bank_prod         REAL NOT NULL DEFAULT 0,
  prev_bank_prod_shared  REAL NOT NULL DEFAULT 0,
  prev_bank_dev          REAL NOT NULL DEFAULT 0,
  prev_bank_dev_shared   REAL NOT NULL DEFAULT 0,
  prev_central_prod      REAL NOT NULL DEFAULT 0,
  prev_central_dev       REAL NOT NULL DEFAULT 0,
  saved_at             TEXT    NOT NULL
);

-- 정기점검 보고서에 넣기로 고른 항목들.
-- kind: 'sr' = 케이스 번호, 'jira' = 이슈 키.
-- 단계를 옮겨다녀도 선택이 남아야 해서 저장한다.
CREATE TABLE IF NOT EXISTS report_picks (
  month TEXT    NOT NULL,
  kind  TEXT    NOT NULL,
  ref   TEXT    NOT NULL,
  ord   INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (month, kind, ref)
);

-- 정기점검 보고서에 넣을 현장 사진.
-- 슬라이드 2장에 2장씩, 넉 장까지. slot 1..4 가 그 순서다.
--
-- 사진 자체를 base64 TEXT 로 담는다. TAS 는 파일시스템이 ephemeral 이라 디스크에 두면
-- 재시작마다 사라지고, base64 로 두면 SQLite 의 BLOB 과 Postgres 의 BYTEA 를 가르지
-- 않는다(attachment_jobs.payload 와 같은 이유).
--
-- 보관은 **그 달 것만**이다. 장당 4MB 씩 넉 장이라 달마다 쌓이면 DB 가 사진 보관소가
-- 된다. 새 사진을 저장할 때 다른 달 행을 치운다(lib/reportPhotos.ts 의 keepOnlyMonth) —
-- 지난달 사진은 그 달 보고서 파일 안에 이미 들어 있다.
CREATE TABLE IF NOT EXISTS report_photos (
  month     TEXT    NOT NULL,
  slot      INTEGER NOT NULL,
  file_name TEXT    NOT NULL DEFAULT '',
  mime      TEXT    NOT NULL DEFAULT '',
  data      TEXT    NOT NULL DEFAULT '',
  bytes     INTEGER NOT NULL DEFAULT 0,
  saved_at  TEXT    NOT NULL,
  PRIMARY KEY (month, slot)
);

-- 팀 = 공용 브로드컴 계정 단위.
-- 한 팀이 계정 하나를 공유한다. 다른 팀이 들어오면 자기 팀 계정을 쓴다.
-- 세션·기기신뢰는 계정에 묶이므로 팀마다 각각(팀 안에서는 하나를 공유).
-- broadcom_username 은 어느 공용 계정인지 식별용 라벨. 비밀번호는 여기 넣지 않는다.
CREATE TABLE IF NOT EXISTS teams (
  team_id           TEXT PRIMARY KEY,
  team_name         TEXT NOT NULL DEFAULT '',
  broadcom_username TEXT NOT NULL DEFAULT '',
  -- 가입 초대 코드. 이 코드로 가입하면 이 팀의 member 가 된다. 비면 가입을 받지 않는다.
  invite_code       TEXT NOT NULL DEFAULT '',
  created_at        TEXT NOT NULL
);

-- 감사 로그.
-- 쓰기(작성/답변)는 공용 계정으로 나가지만, 우리 서비스 사용자 중 누가 시켰는지 남긴다.
-- actor 는 챗봇이 넘긴 요청 사용자 식별자(사번/이메일 등, 합의 필요).
-- result: 'ok' 또는 'failed:<code>'.
CREATE TABLE IF NOT EXISTS audit_log (
  log_id      INTEGER PRIMARY KEY AUTOINCREMENT,
  at          TEXT    NOT NULL,
  actor       TEXT    NOT NULL DEFAULT '',
  team_id     TEXT    NOT NULL DEFAULT '',
  action      TEXT    NOT NULL,
  request_id  INTEGER,
  result      TEXT    NOT NULL DEFAULT '',
  detail      TEXT    NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_audit_at ON audit_log(at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_team ON audit_log(team_id, at DESC);

-- 팀별 MCP 접속 토큰.
-- token_hash 는 평문 토큰의 SHA-256 해시(hex)다. 평문 토큰은 어디에도 저장하지 않는다
-- (발급 시 호출자에게 딱 한 번 반환할 뿐이다).
-- revoked = 1 이면 검증에서 거부한다. 삭제하지 않고 이력으로 남긴다.
CREATE TABLE IF NOT EXISTS team_tokens (
  token_hash   TEXT PRIMARY KEY,
  team_id      TEXT NOT NULL,
  label        TEXT NOT NULL DEFAULT '',
  created_at   TEXT NOT NULL,
  last_used_at TEXT,
  revoked      INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_team_tokens_team ON team_tokens(team_id);

-- 팀별 외부 연동(Jira 등) 자격.
-- kind 로 연동 종류를 구분한다("jira" 등) — 앞으로 다른 연동도 같은 틀을 쓴다.
-- secret_enc 는 토큰 등 민감값을 AES-256-GCM 으로 암호화한 것(lib/secretBox.ts).
-- 평문은 여기 절대 들어가지 않는다. 암호화 키(SR_SECRET_KEY)가 없으면 저장 자체를 거부한다.
-- **더 이상 쓰지 않는다.** 연동 설정 화면을 걷어내면서 읽고 쓰는 코드가 모두 없어졌다
-- (app/settings/page.tsx 주석에 근거). 정의만 남겨 둔다 — 여기서 지우면 새로 만드는 DB
-- 에는 없고 이미 돌고 있는 DB 에는 남아 둘이 어긋난다. 실제로 지우려면 의도적인
-- 마이그레이션이 필요하고, 그 안의 옛 설정은 되돌릴 수 없다.
CREATE TABLE IF NOT EXISTS team_integrations (
  team_id    TEXT NOT NULL,
  kind       TEXT NOT NULL,
  base_url   TEXT NOT NULL DEFAULT '',
  project    TEXT NOT NULL DEFAULT '',
  secret_enc TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL,
  PRIMARY KEY (team_id, kind)
);

CREATE INDEX IF NOT EXISTS idx_team_integrations_team ON team_integrations(team_id);

-- LLM 연결 설정.
-- 지금은 전역 단일 활성 연결(llm_id='default'). 앞으로 여러 개가 필요하면 id 로 늘린다.
-- 요약·리포트·답변요약이 이 설정을 읽어 OpenAI 대신 지정한 엔드포인트를 쓴다.
-- auth_kind:
--   keycloak = 호출마다 token_url 에서 액세스 토큰 발급(비밀번호 그랜트) 후 Bearer 로 사용
--   bearer   = secret_enc 를 그대로 Bearer 토큰(API 키)으로 사용
--   none     = 인증 헤더 없음
-- secret_enc 는 비밀번호(또는 API 키)를 AES-256-GCM 으로 암호화한 것(lib/secretBox.ts).
-- 평문은 여기 절대 들어가지 않는다. 키(SR_SECRET_KEY)가 없으면 저장을 거부한다.
-- 팀별 세션/기기신뢰 상태의 durable 백업.
-- session.json(Playwright storageState)·device.json(MFA 신뢰기기) 을 통째 JSON 으로 담는다.
-- TAS 파일시스템은 재시작마다 초기화되므로, 로그인/persist 때 여기로 밀어넣고(persist)
-- 컨테이너 시작·쓰기 전에 여기서 파일로 복원한다(hydrate). 파일 로직 자체는 그대로 둔다.
CREATE TABLE IF NOT EXISTS team_session_state (
  team_id      TEXT PRIMARY KEY,
  session_json TEXT NOT NULL DEFAULT '',
  device_json  TEXT NOT NULL DEFAULT '',
  updated_at   TEXT NOT NULL DEFAULT ''
);

-- 포털(브로드컴) 공용 계정. 자동 로그인이 쓰는 그 계정이다.
--
-- 전에는 .env 의 SR_USERNAME/SR_PASSWORD 뿐이었다. 그런데 이 계정은 주기적으로
-- 비밀번호를 바꾸는 공용 계정이고, .env 는 **세 군데(이 PC·수집기 VM·드롭릿)**에
-- 사본이 있어서 회전마다 사람이 파일을 찾아 고치고 재배포해야 했다. 한 곳만
-- 빠뜨리면 그 프로세스가 옛 비밀번호로 계속 로그인을 시도한다(= 계정 잠금).
-- 그래서 화면에서 바꿀 수 있게 DB 로 옮긴다. 두 경로 모두 같은 DB 를 본다.
--
-- password_enc 는 AES-256-GCM(lib/secretBox.ts). 평문은 여기 절대 들어가지 않고,
-- 키(SR_SECRET_KEY)가 없으면 저장 자체를 거부한다 — 평문 폴백은 없다.
-- 이 행이 없으면 .env 로 폴백한다(lib/portalCredentials.ts). 기존 설치가 그대로 돈다.
CREATE TABLE IF NOT EXISTS portal_credentials (
  team_id      TEXT PRIMARY KEY,
  username     TEXT NOT NULL DEFAULT '',
  password_enc TEXT NOT NULL DEFAULT '',
  updated_at   TEXT NOT NULL DEFAULT '',
  -- 누가 바꿨나. 공용 계정이라 "언제 누가 돌렸는지" 가 사고 조사의 출발점이다.
  updated_by   TEXT NOT NULL DEFAULT ''
);

-- 자동 로그인 잠금 방지 상태.
--
-- 왜 DB 인가: 수집기는 회차마다 **새 프로세스**로 뜬다(worker 가 collect.ts 를 자식으로
-- 돌린다). 메모리 카운터는 매번 0 에서 시작하므로 "두 번 틀렸으면 멈춘다" 를 지킬 수
-- 없다. 프로세스 밖에 남아야 한다.
--
-- fail_count   연속 실패 횟수. **비밀번호를 실제로 제출한** 시도만 센다
--              (입력칸을 못 찾아 끝난 회차는 IdP 의 실패 카운터와 무관하다).
-- blocked      1 이면 자동 시도를 하지 않는다. **시간이 지나도 저절로 풀리지 않는다** —
--              사람이 새 비밀번호를 저장하거나 로그인 버튼을 눌러야 풀린다.
-- blocked_at   언제 멈췄는지(ISO). 화면 표기용.
--
-- 쿨다운(몇 시간 뒤 자동 재시도)을 두지 않는 이유: 비밀번호가 틀린 상태는 시간이 지나도
-- 그대로다. 몇 시간 뒤에 혼자 다시 찔러 보면 IdP 의 실패 카운터만 한 칸 더 올린다.
-- 고칠 수 있는 것은 사람뿐이므로, 사람이 손을 쓸 때까지 **가만히 있는다.**
--
-- OTP 를 요구받은 회차는 **성공에 가깝게** 취급해 카운터를 0 으로 되돌린다 — OTP 화면이
-- 떴다는 것은 비밀번호가 통과했다는 뜻이다. 이걸 실패로 세면 기기신뢰가 만료된 날
-- 멀쩡한 비밀번호를 잠금 위험으로 오인해 수집을 멈춘다.
CREATE TABLE IF NOT EXISTS portal_login_guard (
  team_id         TEXT PRIMARY KEY,
  fail_count      INTEGER NOT NULL DEFAULT 0,
  blocked         INTEGER NOT NULL DEFAULT 0,
  blocked_at      TEXT NOT NULL DEFAULT '',
  last_attempt_at TEXT NOT NULL DEFAULT '',
  last_result     TEXT NOT NULL DEFAULT '',
  last_reason     TEXT NOT NULL DEFAULT '',
  updated_at      TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS llm_connections (
  llm_id        TEXT PRIMARY KEY,
  name          TEXT    NOT NULL DEFAULT '',
  model_id      TEXT    NOT NULL DEFAULT '',
  base_url      TEXT    NOT NULL DEFAULT '',
  auth_kind     TEXT    NOT NULL DEFAULT 'keycloak',
  token_url     TEXT    NOT NULL DEFAULT '',
  client_id     TEXT    NOT NULL DEFAULT '',
  auth_username TEXT    NOT NULL DEFAULT '',
  secret_enc    TEXT    NOT NULL DEFAULT '',
  chat_path     TEXT    NOT NULL DEFAULT '/v1/chat/completions',
  max_tokens    INTEGER NOT NULL DEFAULT 512,
  temperature   REAL    NOT NULL DEFAULT 0.1,
  system_prompt TEXT    NOT NULL DEFAULT '',
  updated_at    TEXT    NOT NULL DEFAULT ''
);

-- 프로세스 사이에 남겨야 하는 작은 값들(워터마크 등).
-- TAS 는 파일시스템이 ephemeral 이라 파일에 두면 재시작마다 사라진다.
CREATE TABLE IF NOT EXISTS app_state (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT ''
);

-- 케이스 대화의 한국어 번역.
-- scope 는 'thread'(스레드 한 건) 또는 'case_desc'(최초 등록 본문)이고 ref_id 는 그 id 다.
-- 스레드는 한 번 오면 바뀌지 않으므로 한 번 번역하면 다시 부르지 않는다.
-- 첨부를 주고받는 작업 큐.
--
-- 첨부는 supportftp(CrushFTP)에 있고, 거기 로그인은 **진짜 브라우저**가 있어야 끝난다
-- (redirect.html 이 JS 로 이동시킨다). 웹 컨테이너에는 브라우저가 없으므로 수집기 VM 이
-- 대신 처리한다. 웹이 여기에 행을 넣고 worker 가 집어간다.
--
-- payload 는 base64 다. SQLite 의 BLOB 과 Postgres 의 BYTEA 를 가르지 않으려고 문자열로
-- 둔다(용량은 33% 늘지만 상한이 작다).
--
-- 업로드는 올린 뒤에도 남긴다(14일). supportftp 의 files_from_customer 는 보관소가 아니라
-- 투입구라 Broadcom 이 가져가면 비워지고, 그러면 우리가 올린 파일을 우리가 다시 받을 길이
-- 없다 — 이 행이 유일한 사본이다. 다운로드는 받아 둔 임시본이라 24시간만 두고 치운다.
-- 자세한 근거는 lib/attachmentJobs.ts 머리말과 UPLOAD_KEEP_MS 주석에 있다.
CREATE TABLE IF NOT EXISTS attachment_jobs (
  job_id      INTEGER PRIMARY KEY AUTOINCREMENT,
  kind        TEXT    NOT NULL,                     -- upload | download
  request_id  INTEGER NOT NULL,
  document_id INTEGER NOT NULL DEFAULT 0,           -- 다운로드일 때 attachments.document_id
  file_name   TEXT    NOT NULL DEFAULT '',
  payload     TEXT    NOT NULL DEFAULT '',          -- base64. 업로드는 남기고 다운로드는 비운다
  state       TEXT    NOT NULL DEFAULT 'pending',   -- pending | running | done | failed
  error       TEXT    NOT NULL DEFAULT '',
  actor       TEXT    NOT NULL DEFAULT '',
  -- 어느 팀(공용 계정) 일인가. 끝낸 뒤 감사 로그를 **수집기가** 남기는데, 그 한 줄에
  -- 팀이 필요하다. 이게 없던 동안 수집기는 기본 팀으로 적었고, 큐에 넣은 쪽(웹)이
  -- 남긴 'queued' 줄과 팀이 어긋났다. 옛 행은 빈 값이고 그때는 기본 팀으로 본다.
  team_id     TEXT    NOT NULL DEFAULT '',
  created_at  TEXT    NOT NULL,
  updated_at  TEXT    NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_attachment_jobs_state ON attachment_jobs(state, job_id);

CREATE TABLE IF NOT EXISTS text_translations (
  scope      TEXT NOT NULL,
  ref_id     INTEGER NOT NULL,
  lang       TEXT NOT NULL,
  text       TEXT NOT NULL DEFAULT '',
  model      TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (scope, ref_id, lang)
);

-- ── 앱 사용자(신원) ─────────────────────────────────────────────────
--
-- 지금까지 이 앱에는 "누가 쓰고 있는지" 라는 개념이 없었다. 감사 로그의 actor 는
-- 화면이 보내는 값이라 **빈 문자열**이었고, 캘린더·작업 기록처럼 "누가" 가 핵심인
-- 기능은 그 칸을 둘 곳이 없었다. 여기서 신원을 만든다.
--
-- 목적은 **방어가 아니라 귀속**이다(사내망 전제). 그래서 비밀번호 정책·2단계 인증·
-- 잠금 같은 장치는 두지 않는다. 대신 다음 둘은 지킨다.
--   1. 비밀번호 원문은 어디에도 저장하지 않는다(scrypt 해시만).
--   2. 세션 토큰 원문도 저장하지 않는다(SHA-256 해시만) — team_tokens 와 같은 방식이다.
--
-- login_id 는 소문자로 정규화해 넣는다(대소문자가 다른 같은 사람을 둘로 만들지 않게).
-- jira_account_id 는 캘린더 일정을 Jira 에 올릴 때 assignee 로 쓴다. 비면 담당자
-- 없이 올리고 화면이 그 사실을 알려 준다(조용히 넘기지 않는다).
CREATE TABLE IF NOT EXISTS users (
  user_id         INTEGER PRIMARY KEY AUTOINCREMENT,
  login_id        TEXT    NOT NULL,
  display_name    TEXT    NOT NULL DEFAULT '',
  password_hash   TEXT    NOT NULL DEFAULT '',
  jira_account_id TEXT    NOT NULL DEFAULT '',
  -- 개인 노션 연결. 메모장의 메모를 **자기 노션**으로 올리는 데 쓴다.
  --   notion_token_enc   integration 토큰. AES-256-GCM 으로만 저장한다(lib/secretBox.ts).
  --                      SR_SECRET_KEY 가 없으면 **저장을 거부**한다 — 평문 폴백은 없다.
  --   notion_parent_page 메모 페이지를 그 아래에 만든다. 32자 id(비밀값 아님).
  -- 팀 공용이 아니라 사람별이다. 토큰은 그 사람의 노션 전체에 쓰이는 열쇠라, 팀 하나로
  -- 두면 한 사람의 노션이 팀 전체에 열린다.
  notion_token_enc   TEXT NOT NULL DEFAULT '',
  notion_parent_page TEXT NOT NULL DEFAULT '',
  created_at      TEXT    NOT NULL,
  last_login_at   TEXT    NOT NULL DEFAULT '',
  -- 1 이면 로그인을 거부한다. 지우지 않는 이유: 이 사람이 등록한 일정·기록의 작성자
  -- 표시가 사라지면 "누가 했는지" 를 복원할 수 없다.
  disabled        INTEGER NOT NULL DEFAULT 0
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_users_login ON users(login_id);

-- 앱 로그인 세션. 쿠키에 담기는 토큰의 **해시**만 둔다.
-- expires_at 을 넘기면 거부하고, revoked = 1 이면(로그아웃) 즉시 거부한다.
CREATE TABLE IF NOT EXISTS user_sessions (
  token_hash   TEXT PRIMARY KEY,
  user_id      INTEGER NOT NULL,
  created_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL DEFAULT '',
  revoked      INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_user_sessions_user ON user_sessions(user_id);

-- 사람 ↔ 팀. 한 사람이 여러 팀에 속할 수 있다(지원 인력이 두 팀을 겸하는 경우).
-- role: owner = 팀 설정·초대 코드·브로드컴 계정을 바꿀 수 있다 / member = 나머지.
CREATE TABLE IF NOT EXISTS team_members (
  team_id   TEXT    NOT NULL,
  user_id   INTEGER NOT NULL,
  role      TEXT    NOT NULL DEFAULT 'member',
  joined_at TEXT    NOT NULL,
  PRIMARY KEY (team_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_team_members_user ON team_members(user_id);

-- 케이스를 **사람마다** 어디까지 읽었나.
--
-- 전에는 case_reads 가 팀 공유였다(request_id 하나가 기본키). 한 사람이 열면 모두의
-- '새 답변' 배지가 사라져서, 다른 사람은 그 답변을 못 보고 지나갔다. 사람이 생긴 뒤에는
-- 그 칸이 사람마다 있어야 한다.
--
-- ## 옛 표를 지우지 않는다
--
-- 기본키를 바꾸는 마이그레이션은 SQLite 에서 표를 다시 만들어야 하고, 그 사이에 운영
-- 데이터를 들고 옮겨야 한다. 대신 **새 표를 두고 옛 표를 바닥값으로 읽는다**:
-- 읽은 시점 = MAX(내 기록, 팀 공유 기록). 그래서
--   - 이미 팀이 읽어 둔 케이스는 **모두에게 그대로 읽은 상태**로 남는다(바꾸는 날
--     미읽음 숫자가 치솟지 않는다),
--   - 그 뒤에 온 답변은 **사람마다** 따로 센다.
-- 옛 표에는 더 이상 쓰지 않는다. 그래서 바닥값은 고정이고 시간이 지나면 의미가 옅어진다.
CREATE TABLE IF NOT EXISTS case_reads_user (
  request_id          INTEGER NOT NULL,
  user_id             INTEGER NOT NULL,
  last_read_thread_ms INTEGER NOT NULL DEFAULT 0,
  read_at             TEXT    NOT NULL,
  PRIMARY KEY (request_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_case_reads_user ON case_reads_user(user_id, request_id);

-- ── 팀 캘린더 ────────────────────────────────────────────────────────
--
-- "누가 언제 무엇을 하는가" 를 팀이 한 화면에서 본다. 일정은 **팀 전체 공개**다
-- (개인 비공개 일정을 두지 않는다 — 공유가 목적이고, 숨은 일정이 있으면 주간 정리의
-- 집계가 조용히 틀어진다).
--
-- ## 날짜를 왜 문자열 날짜·시각으로 쪼개 두나
--
-- start_date/end_date 는 'YYYY-MM-DD', start_time/end_time 은 'HH:MM' 이고
-- 시각이 비면 **종일**이다. epoch 나 ISO 타임스탬프 하나로 두지 않는 이유:
--
--   1. 달 그리드는 "그 날짜 칸에 걸치는가" 만 묻는다. 날짜 문자열 비교로 끝난다.
--   2. 이 앱은 KST 로 쓰는데 서버는 UTC 일 수 있다. 타임스탬프로 두면 자정 무렵 일정이
--      **하루 밀려** 다른 칸에 그려진다(lib/jiraWrite.ts 의 today() 가 같은 함정을 보정
--      하고 있다). "11월 25일" 은 시간대가 아니라 날짜다 — 그대로 저장한다.
--
-- state: planned(예정) | doing(진행) | done(완료) | canceled(취소)
--   취소는 **일정을 지우는 것과 다르다.** 취소는 "하기로 했는데 안 했다" 는 기록이고
--   삭제는 "그 일정이 없었다" 다. 주간 정리에서 둘을 다르게 센다.
--
-- jira_wanted: **이 일정을 Jira 에 올릴 것인가.** 쓰는 사람이 저장할 때 고른다.
--   0 이면 메모지다 — 사내에만 남고 Jira 로 나가지 않는다. 일정 중에 Jira 로 올릴
--   일이 아닌 것(개인 일정·공유 메모·기억용 기록)이 훨씬 많아서, 새로 적는 일정은
--   기본이 0 이다. 기존 행과 Jira 에서 가져온 행은 1 이다(DEFAULT 1 — 이미 올라가
--   있는 이슈와의 연결이 끊기면 안 된다).
--
--   의도(jira_wanted)와 결과(jira_state)를 나눠 둔다. 한 칸에 섞으면 "올리기로 했는데
--   실패한 것" 과 "애초에 안 올리는 것" 을 구분할 수 없고, 그러면 재시도 대상을 고를
--   수 없다.
--
-- jira_*: 캘린더 → Jira 연동(S5)이 쓰는 칸. jira_state:
--   none    아직 올리지 않았다
--   ok      올라갔고 jira_key 가 유효하다
--   unknown **만들어졌는지 모른다**(타임아웃·5xx). 멱등 라벨로 찾아 입양해야 한다
--   failed  거절당했다(사유는 jira_error)
CREATE TABLE IF NOT EXISTS team_events (
  event_id         INTEGER PRIMARY KEY AUTOINCREMENT,
  team_id          TEXT    NOT NULL,
  title            TEXT    NOT NULL DEFAULT '',
  body             TEXT    NOT NULL DEFAULT '',
  kind             TEXT    NOT NULL DEFAULT '',
  -- Jira 사내 양식(lib/jiraHouseStyle.ts). 태그에서 갈라 둔 값이다.
  --   scopes : 전산망/센터. '/' 로 이어 둔다('개발/운영'). 제목 앞 대괄호가 된다
  --   corp   : 법인('은행'|'중앙회'|'본사'). 상위 에픽을 고른다
  -- 태그 원문은 kind 와 이 둘로 나뉘어 들어간다 — 되돌릴 때 셋을 합쳐 다시 만든다.
  scopes           TEXT    NOT NULL DEFAULT '',
  corp             TEXT    NOT NULL DEFAULT '',
  start_date       TEXT    NOT NULL,
  end_date         TEXT    NOT NULL,
  start_time       TEXT    NOT NULL DEFAULT '',
  end_time         TEXT    NOT NULL DEFAULT '',
  -- 담당자. users.user_id. 팀원과 못 맞춘 이름은 assignee_label 에 글자로 남긴다
  -- (조용히 버리면 "@민수" 라고 적은 사람은 담당자가 들어갔다고 믿는다).
  assignee_user_id INTEGER,
  assignee_label   TEXT    NOT NULL DEFAULT '',
  state            TEXT    NOT NULL DEFAULT 'planned',
  created_by       INTEGER,
  created_at       TEXT    NOT NULL,
  updated_at       TEXT    NOT NULL,
  jira_wanted      INTEGER NOT NULL DEFAULT 1,
  jira_key         TEXT    NOT NULL DEFAULT '',
  jira_url         TEXT    NOT NULL DEFAULT '',
  jira_state       TEXT    NOT NULL DEFAULT 'none',
  jira_error       TEXT    NOT NULL DEFAULT '',
  -- 몇 번 시도했나. 조건으로 대상을 고르는 구조라(sr_jira_links.publish_tries 와 같은
  -- 이유) 영구히 실패하는 건을 매 회차 다시 집어 Jira 를 때린다. 상한을 두려고 센다.
  jira_tries       INTEGER NOT NULL DEFAULT 0,
  jira_synced_at   TEXT    NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_team_events_team_date ON team_events(team_id, start_date);
CREATE INDEX IF NOT EXISTS idx_team_events_jira ON team_events(jira_state, event_id);

-- 일정에 달리는 메모 — "누가 무슨 내용을 했는지" 적어 두는 자리.
-- 이게 그대로 **주간 자동 정리(S6)의 재료**다. 그래서 작성자를 반드시 남긴다.
CREATE TABLE IF NOT EXISTS event_notes (
  note_id    INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id   INTEGER NOT NULL,
  user_id    INTEGER,
  author     TEXT    NOT NULL DEFAULT '',
  body       TEXT    NOT NULL DEFAULT '',
  created_at TEXT    NOT NULL,
  -- Jira 코멘트로 올린 시각. 빈 값이면 아직 안 올렸다.
  --
  -- 왜 자동으로 올리지 않나: 메모에는 고객사 상황이 적힐 수 있고, Jira 코멘트는
  -- 지워도 알림이 이미 간 뒤다. 그래서 **사람이 골라** 올린다. 이 칸은 두 번 올리는
  -- 것을 막고, 어느 메모가 밖으로 나갔는지 화면에서 구분해 보여 주기 위한 것이다.
  jira_posted_at TEXT NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_event_notes_event ON event_notes(event_id, note_id);

-- 주간 자동 정리.
--
-- 그 주의 일정(team_events)과 메모(event_notes)를 모아 개조식으로 정리한 글.
-- "누가 무엇을 했는지 적어두면 알아서 정리된다" 의 결과물이 여기 쌓인다.
--
-- week 는 그 주 **월요일**의 'YYYY-MM-DD'. 주의 기준을 한 값으로 고정해 두면
-- 같은 주를 두 번 만들어도 덮어쓰기로 끝난다((team_id, week) 기본키).
--
-- source: llm = LLM 이 다듬은 것 / rule = 규칙 기반 집계.
--   **LLM 이 없거나 실패해도 정리는 나온다.** 이 레포의 기존 철학과 같다(요약이
--   실패해도 알림은 나간다). 어느 쪽으로 만들어졌는지 화면이 말해 준다.
CREATE TABLE IF NOT EXISTS weekly_digests (
  team_id    TEXT NOT NULL,
  week       TEXT NOT NULL,
  body       TEXT NOT NULL DEFAULT '',
  source     TEXT NOT NULL DEFAULT 'rule',
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (team_id, week)
);
-- 메모장. **일정에 붙지 않는 메모**다.
--
-- event_notes 와 다르다 — 그쪽은 일정 하나에 달려 "그 일을 하며 무엇을 했는지" 를
-- 적고 주간 정리의 재료가 된다. 여기는 날짜에 걸지 않고 그냥 적어 두는 자리다
-- (회의 내용·조사 결과·인수인계·설정 값). 캘린더에 억지로 날짜를 붙여 적던 것을
-- 가를 자리가 없어서 만들었다.
--
-- 노션으로 올린 결과는 **여기 없다.** 노션 연결이 사람별이라(users.notion_token_enc)
-- 같은 메모가 사람마다 다른 페이지로 간다. 그 짝을 note_notion_pages 가 들고 있다.
CREATE TABLE IF NOT EXISTS team_notes (
  note_id          INTEGER PRIMARY KEY AUTOINCREMENT,
  team_id          TEXT    NOT NULL,
  title            TEXT    NOT NULL DEFAULT '',
  body             TEXT    NOT NULL DEFAULT '',
  -- 쉼표로 이은 글자. 목록에서 거르는 데만 쓴다 — 표를 하나 더 두기에는 이르다.
  tags             TEXT    NOT NULL DEFAULT '',
  created_by       INTEGER,
  created_at       TEXT    NOT NULL,
  updated_at       TEXT    NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_team_notes_team ON team_notes(team_id, updated_at);

-- 메모 한 건을 **누가 자기 노션의 어느 페이지로** 올렸는가.
--
-- 노션 연결이 사람별이므로 (메모, 사람) 짝마다 페이지가 하나다. 한 칸으로 두면 먼저
-- 올린 사람의 페이지 id 가 남고, 다음 사람이 올릴 때 그 페이지를 고치려 든다 — 남의
-- 노션이라 404 가 오고, 사람은 무엇이 틀렸는지 알 수 없다.
--
-- state: none 은 행이 없는 것과 같으므로 적지 않는다. ok | failed 둘만 쓴다.
--   "만들어졌는지 모름"(unknown)을 두지 않는다 — 노션은 페이지 생성 응답으로 id 를
--   돌려주고, 멱등 라벨로 찾아올 길이 없다. 타임아웃이면 실패로 적고 사람이 노션을
--   보게 한다. 추측해서 두 번 만드는 것보다 낫다.
CREATE TABLE IF NOT EXISTS note_notion_pages (
  note_id    INTEGER NOT NULL,
  user_id    INTEGER NOT NULL,
  page_id    TEXT    NOT NULL DEFAULT '',
  url        TEXT    NOT NULL DEFAULT '',
  state      TEXT    NOT NULL DEFAULT 'ok',
  error      TEXT    NOT NULL DEFAULT '',
  tries      INTEGER NOT NULL DEFAULT 0,
  synced_at  TEXT    NOT NULL DEFAULT '',
  PRIMARY KEY (note_id, user_id)
);
`;
